// The prose of the journal-entry scenario library, in every language the site
// publishes. The debits and credits themselves live in ./journalScenarios —
// one entry, one set of lines, worded for whoever is reading it.
//
// Each language is complete rather than Partial: a scenario that fell back to
// English would put four English sentences in the middle of a translated page,
// and a reader looking for the right entry would have no way to tell whether
// the gap was the wording or the accounting. tests/i18n/journalScenarios.test.ts
// holds that line.

import type { LanguageCode } from "@/lib/i18n/config";
import type { ScenarioCategory, ScenarioId } from "./journalScenarios";

/** The four prose fields of one worked example. */
export type ScenarioText = {
  /** What to call the transaction in the picker. */
  name: string;
  /** The narration the entry loads with — the user edits it from there. */
  narration: string;
  /** Why these accounts, in plain language. */
  explanation: string;
  /** The mistake this entry is most often got wrong by. */
  mistake: string;
};

export type ScenarioBook = {
  categories: Record<ScenarioCategory, string>;
  scenarios: Record<ScenarioId, ScenarioText>;
};


